import os, json

# Persistent counter state (survives node executions)
_STATE = os.path.join(os.path.expanduser("~"), ".looper_counter_state.json")

try:
    with open(_STATE) as f:
        count = int(json.load(f).get("count", 0))
except Exception:
    count = 0

count += 1

if count >= 10:
    count = 0
    result = "true"
else:
    result = "false"

try:
    with open(_STATE, "w") as f:
        json.dump({"count": count}, f)
except Exception:
    pass
